always @(posedge clk) begin
    if (rst == 1'b1) begin
        aes_state <= AES_ST_ROUND_OP;
    end else begin
        aes_state <= aes_state_next;
    end
end

AES_ST_IDLE: begin
    dcnt_next_mux = 4'h0;
    aes_state_next = AES_ST_ROUND_OP;
end

AES_ST_ROUND_OP: begin
    if (ld == 1'b1) begin
        dcnt_next_mux = 4'hb;
    end else if (dcnt > 4'h0) begin
        dcnt_next_mux = dcnt - 4'h1;
    end else begin
        dcnt_next_mux = 4'h0;
    end
    aes_state_next = AES_ST_ROUND_OP;
end

